export const getSession = async (sessionId: string): Promise<DiffModel> => {
  try {
    const response = await api.get<DiffModel>(`/sessions/${sessionId}`);
    return response.data;
  } catch (error) {
    if (error instanceof APIError) {
      throw error;
    }
    throw new APIError(
      'Failed to get session',
